-- State transitions declared for PasswordResetToken: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION sapiens.password_reset_tokens_is_used_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."is_used" IS DISTINCT FROM OLD."is_used" AND NOT (
           (COALESCE(OLD."is_used"::text, ''), COALESCE(NEW."is_used"::text, '')) IN (('false', 'true'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: password_reset_tokens.is_used % -> %', OLD."is_used", NEW."is_used"
            USING ERRCODE = 'check_violation', COLUMN = 'is_used', CONSTRAINT = 'tg_password_reset_tokens__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS password_reset_tokens_is_used_transition_check ON sapiens.password_reset_tokens;
CREATE TRIGGER password_reset_tokens_is_used_transition_check
    BEFORE UPDATE OF "is_used" ON sapiens.password_reset_tokens
    FOR EACH ROW EXECUTE FUNCTION sapiens.password_reset_tokens_is_used_transition_check();
